const s=$json.body??$json; const fail=m=>{throw new Error(m)}; const txt=v=>typeof v==='string'?v.trim():''; const num=v=>{const n=Number(v);return Number.isFinite(n)?n:null};
if(s.workflow_contract!=='jbh-vendor-candidate-gate-v1') fail('draft_authority:wrong_upstream_contract');
if(s.ready_for_draft!==true) fail('draft_authority:not_ready_for_draft');
if(s.draft_write_authorized!==true) fail('draft_authority:explicit_authorization_required');
const d=s.shopify_draft;
if(!d||d.status!=='DRAFT'||d.publish_allowed!==false) fail('draft_authority:invalid_draft_contract');
const key=txt(s.idempotency_key), title=txt(d.title), productType=txt(d.product_type), sku=txt(d.sku), price=num(d.price);
if(!/^[A-Za-z0-9][A-Za-z0-9._:-]{7,95}$/.test(key)) fail('draft_authority:invalid_idempotency_key');
if(!title||title.length>180) fail('draft_authority:invalid_title');
if(!productType||productType.length>80) fail('draft_authority:invalid_product_type');
if(!/^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$/.test(sku)) fail('draft_authority:invalid_sku');
if(price===null||price<=0) fail('draft_authority:invalid_price');
const expected={idempotency_key:key,title,vendor:'Juss Beautiful Hair',product_type:productType,sku,price:Number(price.toFixed(2)),status:'DRAFT',publish_allowed:false,inventory_tracked:false,requires_shipping:true};
const query=`query JbhDraftPreflight($query: String!) { productVariants(first: 2, query: $query) { nodes { id sku product { id title status } } } }`;
return [{json:{workflow_contract:'jbh-shopify-draft-writer-v1',expected,preflight_body:{query,variables:{query:`sku:${sku}`}}}}];

const a=$('Require Draft Authority').item.json, r=$json, fail=m=>{throw new Error(m)};
if(!r||typeof r!=='object'||(Array.isArray(r.errors)&&r.errors.length)) fail('shopify_preflight:graphql_errors');
const nodes=r?.data?.productVariants?.nodes;
if(!Array.isArray(nodes)) fail('shopify_preflight:invalid_response');
if(nodes.length) fail('shopify_preflight:sku_exists');
const e=a.expected;
const query=`mutation JbhCreateDraft($input: ProductSetInput!) { productSet(synchronous: true, input: $input) { product { id title status vendor productType variants(first: 2) { nodes { id sku price inventoryItem { tracked requiresShipping } } } } userErrors { field message code } } }`;
const input={title:e.title,status:'DRAFT',vendor:'Juss Beautiful Hair',productType:e.product_type,tags:['jbh-n8n-draft',`jbh-source-key:${e.idempotency_key}`],productOptions:[{name:'Title',position:1,values:[{name:'Default Title'}]}],variants:[{optionValues:[{optionName:'Title',name:'Default Title'}],price:e.price.toFixed(2),sku:e.sku,inventoryItem:{sku:e.sku,tracked:false,requiresShipping:true}}]};
return [{json:{workflow_contract:a.workflow_contract,expected:e,mutation_body:{query,variables:{input}}}}];

const b=$('Block Duplicate + Build DRAFT').item.json, r=$json, fail=m=>{throw new Error(m)};
if(!r||typeof r!=='object'||(Array.isArray(r.errors)&&r.errors.length)) fail('shopify_create:graphql_errors');
const ps=r?.data?.productSet;
if(!ps) fail('shopify_create:missing_product_set');
if(Array.isArray(ps.userErrors)&&ps.userErrors.length) fail('shopify_create:user_errors');
const p=ps.product,e=b.expected,vs=p?.variants?.nodes;
if(!p?.id||p.status!=='DRAFT'||p.title!==e.title||p.vendor!=='Juss Beautiful Hair'||p.productType!==e.product_type) fail('shopify_create:product_mismatch');
if(!Array.isArray(vs)||vs.length!==1) fail('shopify_create:variant_count_mismatch');
const v=vs[0];
if(v.sku!==e.sku||Number(v.price)!==e.price||v?.inventoryItem?.tracked!==false||v?.inventoryItem?.requiresShipping!==true) fail('shopify_create:variant_mismatch');
const query=`query JbhDraftReadback($id: ID!) { product(id: $id) { id title status vendor productType variants(first: 2) { nodes { id sku price inventoryItem { tracked requiresShipping } } } } }`;
return [{json:{workflow_contract:b.workflow_contract,expected:{...e,product_id:p.id,variant_id:v.id},readback_body:{query,variables:{id:p.id}}}}];

const c=$('Validate Create Response').item.json, r=$json, fail=m=>{throw new Error(m)};
if(!r||typeof r!=='object'||(Array.isArray(r.errors)&&r.errors.length)) fail('shopify_readback:graphql_errors');
const p=r?.data?.product,e=c.expected,vs=p?.variants?.nodes;
if(!p?.id||p.id!==e.product_id||p.status!=='DRAFT'||p.title!==e.title||p.vendor!=='Juss Beautiful Hair'||p.productType!==e.product_type) fail('shopify_readback:product_mismatch');
if(!Array.isArray(vs)||vs.length!==1) fail('shopify_readback:variant_count_mismatch');
const v=vs[0];
if(v.id!==e.variant_id||v.sku!==e.sku||Number(v.price)!==e.price||v?.inventoryItem?.tracked!==false||v?.inventoryItem?.requiresShipping!==true) fail('shopify_readback:variant_mismatch');
return [{json:{ok:true,workflow_contract:'jbh-shopify-draft-writer-v1',status:'shopify_draft_verified',idempotency_key:e.idempotency_key,shopify_product_id:p.id,shopify_variant_id:v.id,sku:v.sku,product_status:p.status,publish_allowed:false,inventory_tracked:false,requires_shipping:true,next_gate:'sample + media + separate owner publish approval'}}];
